INSERT INTO duas (id, category, keywords, arabic, transliteration, translation_en, translation_ur, reference, verified)
VALUES
    ('sleep', 'Before Sleeping · Sone Se Pehle Ki Dua', ARRAY['sleep', 'sona', 'sote', 'bed', 'neend', 'sony', 'sone', 'soney', 'sone se pehle'], 'بِاسْمِكَ اللّهُمَّ أَمُوتُ وَأَحْيَا', 'Bismika Allahumma amutu wa ahya', 'In Your name, O Allah, I die and I live.', 'Aey Allah, tere hi naam ke sath main marta hoon aur tere hi naam ke sath jeeta hoon (yani sota aur jagta hoon).', 'Sahih al-Bukhari 6324', TRUE),
    ('waking-up', 'After Waking Up · Neend Se Jagny Ki Dua', ARRAY['wake up', 'jagna', 'jagny', 'morning wake', 'uthna', 'neend se bedar', 'bedaar', 'neend se jagny', 'neend se jagna'], 'الْحَمْدُ لِلّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ', 'Alhamdu lillahil-ladhi ahyana ba''da ma amatana wa ilayhin-nushur', 'All praise is for Allah who gave us life after having taken it from us, and unto Him is the resurrection.', 'Tamam tareefein Allah ke liye hain jisne humein maut (neend) ke baad zindagi ata ki, aur usi ki taraf dobara uthna hai.', 'Sahih al-Bukhari 6312', TRUE),
    ('before-eating', 'Before Eating · Khany Se Pehle Ki Dua', ARRAY['eating', 'khana', 'khaty', 'food', 'meal', 'khany se pehle', 'khany sy phly', 'khana khany se pehle'], 'بِسْمِ اللّهِ', 'Bismillah. (If you forget at the start: Bismillahi awwalahu wa akhirahu)', 'In the name of Allah. If you forget at the beginning, say: "In the name of Allah at the beginning and at the end of it."', 'Allah ke naam se (shuru karta hoon). Agar shuru mein bhool jaye to kahe: "Bismillahi awwalahu wa akhirahu" (shuru mein bhi aur aakhir mein bhi Allah ke naam se).', 'Sunan Abi Dawud 3767', TRUE),
    ('after-eating', 'After Eating · Khany Ke Baad Ki Dua', ARRAY['after eating', 'khany k baad', 'finish meal', 'khany ke baad', 'khane ke baad'], 'الْحَمْدُ لِلّهِ الَّذِي أَطْعَمَنِي هَذَا وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ', 'Alhamdu lillahil-ladhi at''amani hadha wa razaqanihi min ghayri hawlim minni wa la quwwah', 'All praise is for Allah who fed me this and provided it for me without any might or power on my part.', 'Tamam tareefein Allah ke liye hain jisne mujhe ye khana khilaya aur bina meri kisi taqat ya koshish ke mujhe rizq diya.', 'Sunan Abi Dawud 4023', TRUE),
    ('leaving-home', 'Leaving Home · Ghar Se Nikalny Ki Dua', ARRAY['leaving home', 'ghar sy niklna', 'going out', 'bahir jana', 'ghar se nikalne', 'niklny', 'ghar se nikalny', 'ghar se nikalna'], 'بِسْمِ اللّهِ تَوَكَّلْتُ عَلَى اللّهِ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّهِ', 'Bismillahi tawakkaltu ''alallahi wa la hawla wa la quwwata illa billah', 'In the name of Allah, I place my trust in Allah, and there is no might nor power except with Allah.', 'Allah ke naam se (ghar se nikalta hoon), maine Allah par bharosa kiya, aur koi taqat ya qudrat nahi magar Allah ke sath.', 'Sunan Abi Dawud 5095', TRUE),
    ('distress', 'During Distress · Pareshani Ke Waqt Ki Dua', ARRAY['distress', 'pareshan', 'worried', 'anxiety', 'ghum', 'sad', 'stress'], 'لاَ إِلَهَ إِلاَّ اللَّهُ الْعَظِيمُ الْحَلِيمُ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ السَّمَوَاتِ وَالأَرْضِ، رَبُّ الْعَرْشِ الْعَظِيمِ', 'La ilaha illal-lahu Al-`Azim, al-Halim, La ilaha illal-lahu Rabbu-s-samawati wal-ard wa Rabbu-l-arsh il-azim', 'There is no deity but Allah, the Magnificent, the Forbearing. There is no deity but Allah, Lord of the heavens and the earth, Lord of the Mighty Throne.', 'Allah ke siwa koi ibadat ke laiq nahi, jo bohot bara aur bardbaar hai. Allah ke siwa koi ibadat ke laiq nahi jo aasmanon aur zameen ka Rab hai, jo Arsh-e-Azeem ka Rab hai.', 'Sahih al-Bukhari 6345', TRUE),
    ('forgiveness', 'Seeking Forgiveness · Maafi Mangny Ki Dua', ARRAY['forgiveness', 'maafi', 'gunah', 'astaghfirullah', 'sin', 'repent'], 'أَسْتَغْفِرُ اللّهَ الَّذِي لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ وَأَتُوبُ إِلَيْهِ', 'Astaghfirullahil-ladhi la ilaha illa huwal-Hayyul-Qayyumu wa atubu ilayh', 'I seek the forgiveness of Allah, besides whom there is no deity, the Ever-Living, the Sustainer of existence, and I repent unto Him.', 'Main us Allah se maafi mangta hoon jiske siwa koi ibadat ke laiq nahi, jo zinda aur hamesha qaim rehny wala hai, aur main uski taraf tauba karta hoon.', 'Sunan Abi Dawud 1517', TRUE),
    ('travel', 'During Travel · Safar/Sawari Par Baithny Ki Dua', ARRAY['travel', 'safar', 'journey', 'safar par', 'sawari'], 'سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَىٰ رَبِّنَا لَمُنْقَلِبُونَ', 'Subhanal-ladhi sakhkhara lana hadha wa ma kunna lahu muqrinin, wa inna ila rabbina lamunqalibun', 'Glory to Him who has subjected this to us, and we could never have accomplished this by ourselves, and to our Lord we will surely return.', 'Pak hai wo Zaat jisne is (sawari) ko humare qabu mein diya, warna hum khud isay qabu mein nahi la sakte thay, aur beshak hum apne Rab ki taraf lautny wale hain.', 'Sahih Muslim 1342, Quran 43:13-14', TRUE),
    ('entering-masjid', 'Entering Masjid · Masjid Mein Dakhil Hony Ki Dua', ARRAY['masjid', 'mosque', 'entering mosque', 'masjid mein dakhil'], 'اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ', 'Allahumma-ftah li abwaba rahmatik', 'O Allah! open for me the doors of Thy mercy', 'Aey Allah, mere liye apni rehmat ke darwaze khol de.', 'Sahih Muslim 713', TRUE),
    ('after-wudu', 'After Wudu · Wudu Ke Baad Ki Dua', ARRAY['wudu ke baad', 'wudu k baad', 'wudu ke bad', 'after wudu', 'ablution ke baad', 'wudu k bad'], 'أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا عَبْدُ اللَّهِ وَرَسُولُهُ', 'Ashhadu an la ilaha illallah wa ashhadu anna Muhammadan ''abduhu wa rasuluh', 'I testify that there is no god but Allah and that Muhammad is the servant of Allah and His Messenger.', 'Main gawahi deta hoon ke Allah ke siwa koi ibadat ke laiq nahi, aur Muhammad (S.A.W) Allah ke bande aur uske Rasul hain.', 'Sahih Muslim 234', TRUE),
    ('entering-toilet', 'Entering Toilet · Bathroom Mein Dakhil Hony Ki Dua', ARRAY['toilet', 'bathroom', 'washroom', 'bait ul khala', 'toilet mein dakhil', 'toilet jane se pehle', 'bathroom mein jana'], 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ', 'Allahumma inni a''udhu bika minal-khubuthi wal-khaba''ith', 'O Allah, I seek Refuge with You from all offensive and wicked things (evil deeds and evil spirits).', 'Aey Allah, main teri panah maangta hoon har khabees cheez aur khabees jinnat se.', 'Sahih al-Bukhari 142', TRUE),
    ('leaving-toilet', 'Leaving Toilet · Toilet Se Bahir Nikalny Ki Dua', ARRAY['leaving toilet', 'toilet se bahir', 'toilet se bahar', 'toilet se nikalna', 'toilet se nikalny', 'bathroom se bahir', 'toilet ke baad'], 'غُفْرَانَكَ', 'Ghufranak', 'Grant me Thy forgiveness.', 'Aey Allah, main teri maghfirat chahta hoon.', 'Sunan Abi Dawud 30', TRUE),
    ('wearing-clothes', 'Wearing Clothes · Kapry Pehnny Ki Dua', ARRAY['wearing clothes', 'kapry pehnna', 'kapre pehanna', 'kapry pehnty', 'libas pehnna', 'clothes pehnna', 'kapry pehnne ki dua'], 'الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي هَذَا الثَّوْبَ وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ', 'Alhamdu lillahil-ladhi kasani hadha-th-thawba wa razaqanihi min ghayri hawlim minni wa la quwwah', 'Praise be to Allah Who has clothed me with this and provided me with it through no might and power on my part.', 'Tamam tareefein Allah ke liye hain jisne mujhe ye kapra pehnaya aur bina meri kisi taqat ya koshish ke mujhe ata kiya.', 'Sunan Abi Dawud 4023', TRUE),
    ('after-adhan', 'After Adhan · Azan Ke Baad Ki Dua', ARRAY['adhan', 'azan', 'after adhan', 'adhan ke baad', 'adhan k baad', 'azan ke baad', 'azan sunne ke baad'], 'اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ وَالصَّلَاةِ الْقَائِمَةِ آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ', 'Allahumma Rabba hadhihi-d-da''watit-tammah, was-salatil-qa''imah, ati Muhammadanil-wasilata wal-fadilah, wab''ath-hu maqaman mahmudanil-ladhi wa''adtah', 'O Allah! Lord of this perfect call and of the regular prayer which is going to be established, give Muhammad the right of intercession and illustriousness, and resurrect him to the best and the highest place in Paradise that You promised him.', 'Aey Allah, is mukammal pukar aur qaim honay wali namaz ke Rab, Muhammad (S.A.W) ko waseela aur fazilat ata kar, aur unhe us tareef wale maqam tak pohncha jiska tu ne waada kiya hai.', 'Sahih al-Bukhari 614', TRUE),
    ('leaving-masjid', 'Leaving Masjid · Masjid Se Nikalny Ki Dua', ARRAY['leaving masjid', 'masjid se nikalna', 'masjid se nikalny', 'masjid se bahir', 'masjid se bahar', 'masjid chhorna', 'mosque se bahir'], 'اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ', 'Allahumma inni as''aluka min fadlik', 'O Allah! I beg of Thee Thy Grace.', 'Aey Allah, main tera fazl aur karam maangta hoon.', 'Sahih Muslim 713', TRUE),
    ('rain', 'When It Rains · Barish Hony Ki Dua', ARRAY['rain', 'barish', 'raining', 'barish ki dua', 'barsat', 'barish hoti hai', 'when it rains'], 'صَيِّبًا نَافِعًا', 'Sayyiban nafi’an', 'Let it be a strong fruitful rain.', 'Aey Allah, is barish ko khoob faidemand bana.', 'Sahih al-Bukhari 1032', TRUE),
    ('visiting-sick', 'Visiting the Sick · Mareez Ki Iyadat Ki Dua', ARRAY['visiting sick', 'mareez ki iyadat', 'bimar ki iyadat', 'beemar ki iyadat', 'mareez ke paas', 'sick visit', 'iyadat karna'], 'لاَ بَأْسَ طَهُورٌ إِنْ شَاءَ اللَّهُ', 'La ba’sa, tahurun in sha’ Allah', 'Don''t worry, if Allah will, it will be expiation (for your sins).', 'Koi haraj nahi, ye (bimari) gunahon ka kaffara hai, agar Allah ne chaha.', 'Sahih al-Bukhari 5656', TRUE),
    ('wearing-new-clothes', 'Wearing New Clothes · Naye Kapry Pehnny Ki Dua', ARRAY['wearing new clothes', 'naye kapry', 'naya kapra', 'naya libas', 'new dress', 'naye kapre'], 'اللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ كَسَوْتَنِيهِ أَسْأَلُكَ مِنْ خَيْرِهِ وَخَيْرِ مَا صُنِعَ لَهُ وَأَعُوذُ بِكَ مِنْ شَرِّهِ وَشَرِّ مَا صُنِعَ لَهُ', 'Allahumma laka-l-hamdu anta kasawtanihi, as''aluka min khayrihi wa khayri ma suni''a lahu, wa a''udhu bika min sharrihi wa sharri ma suni''a lahu', 'O Allah, praise be to Thee! as Thou hast clothed me with it, I ask Thee for its good and the good of that for which it was made, and I seek refuge in Thee from its evil and the evil of that for which it was made.', 'Aey Allah, teri hi tamam tareefein hain, tu ne hi mujhe ye pehnaya. Main tujh se iski khair aur jis maqsad ke liye ye banaya gaya uski khair maangta hoon, aur iske shar aur us maqsad ke shar se teri panah chahta hoon.', 'Sunan Abi Dawud 4020', FALSE),
    ('sneezing', 'When Sneezing · Cheenk Marne Ki Dua', ARRAY['sneeze', 'sneezing', 'cheenk', 'chink', 'cheenk aana'], 'الْحَمْدُ لِلَّهِ', 'Alhamdu lillah', 'Praise be to Allah. (The listener says: May Allah bestow His Mercy on you; the sneezer replies: May Allah give you guidance and improve your condition.)', 'Tamam tareefein Allah ke liye hain. (Sunne wala kahe: Yarhamukallah; aur cheenkne wala jawab mein kahe: Yahdikumullahu wa yuslihu balakum.)', 'Sahih al-Bukhari 6224', FALSE),
    ('breaking-fast', 'Breaking Fast · Iftar Ke Waqt Ki Dua', ARRAY['iftar', 'roza', 'breaking fast', 'fast', 'ramadan', 'ramzan', 'roza kholna'], 'ذَهَبَ الظَّمَأُ وَابْتَلَّتِ الْعُرُوقُ وَثَبَتَ الأَجْرُ إِنْ شَاءَ اللَّهُ', 'Dhahaba-z-zama''u wabtallati-l-''uruqu wa thabata-l-ajru in sha'' Allah', 'Thirst has gone, the arteries are moist, and the reward is sure, if Allah wills.', 'Pyaas khatam ho gayi, ragein tar ho gayin, aur agar Allah ne chaha to ajr saabit ho gaya.', 'Sunan Abi Dawud 2357', FALSE),
    ('paying-debt', 'Debt Relief · Qarz Ki Adaigi Ki Dua', ARRAY['debt', 'qarz', 'karz', 'loan', 'udhar', 'qarz ki dua'], 'اللَّهُمَّ اكْفِنِي بِحَلاَلِكَ عَنْ حَرَامِكَ وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ', 'Allahumma-kfini bihalalika ''an haramika wa aghnini bifadlika ''amman siwak', 'O Allah, suffice me with Your lawful against Your prohibited, and make me independent of all those besides You.', 'Aey Allah, mujhe apne halal se kaafi kar de aur haram se bacha, aur apne fazl se mujhe apne siwa sab se beniyaz kar de.', 'Jami'' at-Tirmidhi 3563', FALSE),
    ('anger', 'When Angry · Gusse Ke Waqt Ki Dua', ARRAY['anger', 'gussa', 'angry', 'gusse mein', 'ghussa', 'gussa aana'], 'أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ', 'A''udhu billahi minash-shaitanir-rajim', 'I seek refuge with Allah from Satan, the outcast.', 'Main Allah ki panah maangta hoon shaitan mardood se.', 'Sahih al-Bukhari 6115', FALSE),
    ('entering-graveyard', 'Entering Graveyard · Qabristan Mein Dakhil Hony Ki Dua', ARRAY['graveyard', 'qabristan', 'qabr', 'qabar', 'grave', 'qabristan mein dakhil'], 'السَّلاَمُ عَلَيْكُمْ أَهْلَ الدِّيَارِ مِنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ وَإِنَّا إِنْ شَاءَ اللَّهُ لَلَاحِقُونَ أَسْأَلُ اللَّهَ لَنَا وَلَكُمْ الْعَافِيَةَ', 'As-salamu ''alaykum ahlad-diyari minal-mu''minina wal-muslimin, wa inna in sha'' Allahu lalahiqun, as''alullaha lana wa lakumul-''afiyah', 'Peace be upon you, the inhabitants of the city, among the believers and Muslims, and God willing we shall join you. I beg of Allah peace for us and for you.', 'Tum par salamti ho aey is basti ke rehne walo jo momin aur musalman ho. Aur beshak hum bhi, agar Allah ne chaha, tum se milne wale hain. Main Allah se apne liye aur tumhare liye aafiyat maangta hoon.', 'Sahih Muslim 975', FALSE),
    ('drinking-milk', 'After Drinking Milk · Doodh Peeny Ke Baad Ki Dua', ARRAY['milk', 'doodh', 'drink milk', 'doodh peena', 'doodh peeny ke baad'], 'اللَّهُمَّ بَارِكْ لَنَا فِيهِ وَزِدْنَا مِنْهُ', 'Allahumma barik lana fihi wa zidna minhu', 'O Allah! bless us in it and give us more of it.', 'Aey Allah, is (doodh) mein humare liye barkat de aur humein is se zyada ata farma.', 'Sunan Abi Dawud 3730', FALSE),
    ('morning-protection', 'Morning Supplication · Subah Ki Dua', ARRAY['morning dua', 'subah ki dua', 'subah', 'subha', 'morning protection', 'fajr ke baad'], 'بِسْمِ اللَّهِ الَّذِي لاَ يَضُرُّ مَعَ اسْمِهِ شَىْءٌ فِي الأَرْضِ وَلاَ فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ', 'Bismillahil-ladhi la yadurru ma''as-mihi shay''un fil-ardi wa la fis-sama''i wa huwas-Sami''ul-''Alim', 'In the name of Allah, when Whose name is mentioned nothing on Earth or in Heaven can cause harm, and He is the Hearer, the Knower.', 'Allah ke naam se, jiske naam ke sath zameen aur aasman mein koi cheez nuksan nahi de sakti, aur wo sab sunne wala aur sab jaanne wala hai.', 'Sunan Abi Dawud 5088', FALSE),
    ('evening-protection', 'Evening Supplication · Shaam Ki Dua', ARRAY['evening dua', 'shaam ki dua', 'sham ki dua', 'maghrib ke baad', 'shaam', 'evening'], 'أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ', 'A''udhu bi kalimatil-lahit-tammati min sharri ma khalaq', 'I seek refuge in the Perfect Word of Allah from the evil of what He has created.', 'Main Allah ke mukammal kalimaat ki panah maangta hoon har us cheez ke shar se jo usne paida ki.', 'Sahih Muslim 2709a', FALSE),
    ('anxiety-lazy', 'Against Anxiety & Laziness · Fikr Aur Susti Se Nijat Ki Dua', ARRAY['anxiety and laziness', 'susti', 'laziness', 'lazy', 'fikr', 'gham', 'buzdili'], 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ وَالْعَجْزِ وَالْكَسَلِ وَالْبُخْلِ وَالْجُبْنِ وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ', 'Allahumma inni a''udhu bika minal-hammi wal-hazan, wal-''ajzi wal-kasal, wal-bukhli wal-jubn, wa dala''id-dayni wa ghalabatir-rijal', 'O Allah! I seek refuge with You from distress and sorrow, from helplessness and laziness, from miserliness and cowardice, from being heavily in debt and from being overcome by men.', 'Aey Allah, main teri panah maangta hoon fikr aur gham se, be-bassi aur susti se, kanjoosi aur buzdili se, qarz ke bojh se aur mardon ke ghalbe se.', 'Sahih al-Bukhari 2893', FALSE),
    ('increase-knowledge', 'Seeking Knowledge · Ilm Mein Izafay Ki Dua', ARRAY['knowledge', 'ilm', 'study', 'exam', 'padhai', 'parhai', 'ilm mein izafa'], 'رَبِّ زِدْنِي عِلْمًا', 'Rabbi zidni ''ilma', 'My Lord, increase me in knowledge.', 'Aey mere Rab, mere ilm mein izafa farma.', 'Quran 20:114', FALSE),
    ('parents', 'For Parents · Walidain Ki Maghfirat Ki Dua', ARRAY['parents', 'walidain', 'mother', 'father', 'maa baap', 'ammi abbu', 'walidain ki dua'], 'رَبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا', 'Rabbir-hamhuma kama rabbayani saghira', 'My Lord, have mercy upon them as they brought me up when I was small.', 'Aey mere Rab, mere walidain par reham farma jese unhone bachpan mein meri parwarish ki.', 'Quran 17:24', FALSE),
    ('good-dunya-akhirah', 'Good in Both Worlds · Dunya Aur Akhirah Ki Kamyabi', ARRAY['dunya akhirah', 'kamyabi', 'success', 'hasana', 'dunya aur akhirah', 'jannah ki dua'], 'رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ', 'Rabbana atina fid-dunya hasanatan wa fil-akhirati hasanatan wa qina ''adhaban-nar', 'Our Lord, give us in this world that which is good and in the Hereafter that which is good and protect us from the punishment of the Fire.', 'Aey humare Rab, humein dunya mein bhi bhalai de aur akhirat mein bhi bhalai de, aur humein aag ke azab se bacha.', 'Sahih al-Bukhari 4522, Quran 2:201', FALSE),
    ('steadfast-faith', 'Steadfast Faith · Iman Par Qaim Rehny Ki Dua', ARRAY['iman', 'faith', 'steadfast', 'heart', 'dil', 'deen par qaim', 'ya muqallib'], 'يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ', 'Ya Muqallibal-qulubi thabbit qalbi ''ala dinik', 'O Changer of the Hearts! Strengthen my heart upon Your Religion.', 'Aey dilon ko pherne wale, mere dil ko apne deen par saabit rakh.', 'Jami'' at-Tirmidhi 2140', FALSE),
    ('leaving-gathering', 'Leaving a Gathering · Majlis Se Uthny Ki Dua', ARRAY['majlis', 'gathering', 'meeting', 'baithak', 'majlis se uthna', 'kaffara majlis'], 'سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ أَنْتَ أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ', 'Subhanaka Allahumma wa bihamdika, ashhadu an la ilaha illa Anta, astaghfiruka wa atubu ilayk', 'Glory is to You, O Allah, and praise, I bear witness that there is none worthy of worship except You, I seek Your forgiveness, and I repent to You.', 'Aey Allah, tu pak hai apni tareef ke sath, main gawahi deta hoon ke tere siwa koi ibadat ke laiq nahi, main teri maghfirat chahta hoon aur teri taraf tauba karta hoon.', 'Jami'' at-Tirmidhi 3433', FALSE),
    ('protection-evil-eye', 'Protection from Evil Eye · Nazar e Bad Se Hifazat', ARRAY['evil eye', 'nazar', 'nazar e bad', 'buri nazar', 'nazar se hifazat', 'children protection'], 'أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ', 'A''udhu bi kalimatil-lahit-tammati min kulli shaytanin wa hammah, wa min kulli ''aynin lammah', 'I seek Refuge with Your Perfect Words from every devil and from poisonous pests and from every evil, harmful, envious eye.', 'Main Allah ke mukammal kalimaat ki panah maangta hoon har shaitan aur zahreele janwar se, aur har nuksan pohnchane wali buri nazar se.', 'Sahih al-Bukhari 3371', FALSE),
    ('hearing-adhan', 'Responding to Adhan · Azan Ka Jawab Deny Ki Dua', ARRAY['adhan ka jawab', 'azan ka jawab', 'responding adhan', 'repeat after adhan', 'azan sunna', 'jawab e azan'], 'لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ', 'La hawla wa la quwwata illa billah', 'While hearing the Adhan, repeat what the Mu''adhdhin says, but at "Hayya ''alas-salah" and "Hayya ''alal-falah", say: There is neither might nor any power except with Allah.', 'Azan sunte waqt uske alfaaz dohraye jayein, magar "Hayya alas-salah" aur "Hayya alal-falah" par kahein: koi taqat aur qudrat nahi magar Allah ke sath.', 'Sahih al-Bukhari 613', FALSE),
    ('fast-breaking-host', 'Dua for the Host · Mezban Ke Liye Dua', ARRAY['mezban', 'host', 'guest', 'daawat', 'khana khilana', 'daawat ki dua'], 'أَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ وَأَكَلَ طَعَامَكُمُ الأَبْرَارُ وَصَلَّتْ عَلَيْكُمُ الْمَلاَئِكَةُ', 'Aftara ''indakumus-sa''imuna, wa akala ta''amakumul-abraru, wa sallat ''alaykumul-mala''ikah', 'May the fasting (men) break their fast with you, and the pious eat your food, and the angels pray for blessing on you.', 'Tumhare haan rozedar iftar karein, aur tumhara khana nek log khaein, aur farishte tumhare liye dua karein.', 'Sunan Abi Dawud 3854', FALSE)
